import React, { useState } from "react";

const QUESTIONS = [
  { text: "Water boils at 100°C at sea level.", answer: true },
  { text: "Electrons are in the nucleus.", answer: false },
  { text: "Gravity pulls objects toward Earth’s center.", answer: true },
];

function Games() {
  const [score, setScore] = useState(0);
  const [attempts, setAttempts] = useState(0);

  function handleAnswer(isCorrect) {
    setAttempts((a) => a + 1);
    if (isCorrect) setScore((s) => s + 1);
  }

  return (
    <section className="page fade-in">
      <h1 className="slide-up">Science Boost Games</h1>
      <p className="slide-up" style={{ maxWidth: "700px" }}>
        Quick true/false questions to warm up your brain.
      </p>

      <div className="card slide-up">
        <h2>True or False</h2>
        <p><strong>Score:</strong> {score} / {attempts}</p>

        <div className="game-questions">
          {QUESTIONS.map((q, i) => (
            <div key={i} className="game-question">
              <p>{q.text}</p>
              <button className="secondary-btn" onClick={() => handleAnswer(q.answer === true)}>
                True
              </button>
              <button className="secondary-btn" onClick={() => handleAnswer(q.answer === false)}>
                False
              </button>
            </div>
          ))}
        </div>

        <p className="game-tip">
          “Success is the sum of small efforts, repeated day in and day out.”
        </p>
      </div>
    </section>
  );
}

export default Games;
